  public void Initialize(GameRuntime runtime){game=runtime;GameTheme.ButtonStyle(Train,true);var buttonSize=Train.GetComponent<LayoutElement>();buttonSize.minWidth=buttonSize.preferredWidth=104;buttonSize.flexibleWidth=0;buttonSize.minHeight=buttonSize.preferredHeight=44;var modelSize=ModelButton.GetComponent<LayoutElement>();modelSize.minHeight=modelSize.preferredHeight=44;var row=Train.transform.parent.GetComponent<HorizontalLayoutGroup>();row.padding=new RectOffset(6,6,5,5);row.spacing=6;row.childForceExpandHeight=false;row.childControlHeight=true;var height=row.GetComponent<LayoutElement>();height.minHeight=height.preferredHeight=54;Model.resizeTextForBestFit=true;Model.resizeTextMinSize=10;Model.resizeTextMaxSize=12;var heading=transform.Find("HardwareHeading");var controls=WorkshopUIFactory.Horizontal("HardwareControls",transform,44);controls.transform.SetSiblingIndex(heading.GetSiblingIndex());heading.SetParent(controls.transform,false);heading.GetComponent<LayoutElement>().flexibleWidth=1;buyModes=new Button[3];string[] modes={"1","10","max"};for(int i=0;i<3;i++){string mode=modes[i];var b=WorkshopUIFactory.Button("HardwareBuyMode-"+mode,controls.transform,mode=="max"?"MAX":"×"+mode,()=>game.Act(s=>SettingsRules.Change(s,"buy-mode",mode)));var size=b.GetComponent<LayoutElement>();size.minWidth=size.preferredWidth=48;size.minHeight=size.preferredHeight=44;size.flexibleWidth=0;buyModes[i]=b;}tapLabel=game.TapButton.GetComponentInChildren<Text>();trainLabel=Train.GetComponentInChildren<Text>();trainLabel.font=GameTheme.Bold;trainLabel.fontSize=trainLabel.resizeTextMaxSize=13;trainLabel.resizeTextMinSize=11;badge=transform.Find("LaboratoryStage/LabBadge").GetComponent<Text>();guidance=transform.Find("Guidance");var ambient=gameObject.AddComponent<LaboratoryAmbient>();ambient.Initialize(game,(RectTransform)transform.Find("LaboratoryStage"));feedback=game.TapButton.GetComponent<LabFeedback>()??game.TapButton.gameObject.AddComponent<LabFeedback>();feedback.Initialize(Floating);Train.onClick.AddListener(()=>game.UserShow("training"));ModelButton.onClick.AddListener(()=>game.UserShow("training"));}
  void OnEnable(){Canvas.preWillRenderCanvases+=Adapt;Adapt();}void OnDisable(){Canvas.preWillRenderCanvases-=Adapt;}void OnRectTransformDimensionsChange()=>Adapt();void Adapt(){var stage=transform.Find("LaboratoryStage");var canvas=GetComponentInParent<Canvas>();if(stage==null||canvas==null)return;var root=canvas.rootCanvas;var rect=root.renderMode==RenderMode.ScreenSpaceCamera&&root.worldCamera!=null?root.worldCamera.pixelRect:new Rect(0,0,Screen.width,Screen.height);float height=rect.height/Mathf.Max(1,rect.width)<1.9f?180:240;var size=stage.GetComponent<LayoutElement>();if(size!=null&&size.preferredHeight!=height)size.minHeight=size.preferredHeight=height;}
